import re
import logging
import time
from taf.ue.plugin.mtk.controller import Controller
from taf.ue.plugin.mtk.factory import DeploymentMode
from taf.ue.plugin.mtk.commands import ACT, EIMSCFG, ESIMPOWER, EGMC, ESBP, CEDRXS
from taf.ue.plugin.mtk.flow import DetectACT, DetectAPN, LockSACell, LockNSACell, UnlockSACell, UnlockNSACell
from taf.ue.plugin.mtk.exceptions import GetUeIPFailure, NotFoundAccessTechnology, DetectAIDFailure
from taf.ue.plugin.mtk.config import Configuration
from taf.ue.plugin.mtk.mace.factory import (MacePreAttachFactory, MaceAttachFactory, MaceDetachFactory,
                                            MacePDNFactory, MaceRebootFactory, PetrusMaceRebootFactory,
                                            MaceEnableLoggingFactory, PetrusMacePDNFactory,
                                            PetrusMacePreAttachFactory, OppoMacePreAttachFactory,
                                            MaceVoiceCallFactory, CaymusMacePreAttachFactory,
                                            BollingerMacePreAttachFactory)
from taf.ue.plugin.mtk.mace.executor import (RemotePopen, MaceAtCommandExecutor)


class MaceController(Controller):

    def __init__(self, config, mace_proxy):
        super(MaceController, self).__init__()
        self._config = config
        self._mace_proxy = mace_proxy

        self._remote_popen = RemotePopen(self._mace_proxy)
        self._enable_logging_factory = MaceEnableLoggingFactory(self._mace_proxy,
                                                                config)

        self._pre_attach_factory = self._create_pre_attach_factory()

        self._attach_factory = MaceAttachFactory(self._mace_proxy)

        self._detach_factory = MaceDetachFactory(self._mace_proxy)

        self._pdn_factory = self._create_pdn_factory()

        self._reboot_factory = self._create_reboot_factory()

    def _create_pre_attach_factory(self):
        return MacePreAttachFactory(self._mace_proxy, self._config)

    def _create_reboot_factory(self):
        return MaceRebootFactory(self._mace_proxy)

    def _create_pdn_factory(self):
        return MacePDNFactory(self._mace_proxy,
                              self._config)

    def _setup(self):
        pass

    def create_enable_logging(self):
        return self._enable_logging_factory.create()

    def create_attach(self, deployment_mode):
        return self._attach_factory.create(deployment_mode)

    def create_detach(self, deployment_mode):
        return self._detach_factory.create(deployment_mode)

    def create_pre_attach(self, deployment_mode):
        return self._pre_attach_factory.create(deployment_mode)

    def create_reboot(self):
        return self._reboot_factory.create()

    def create_pdn(self, deployment_mode):
        return self._pdn_factory.create(deployment_mode)

    def _teardown(self):
        pass

    def create_deactivate_additional_pdn(self, deployment_mode):
        return self._pdn_factory.create_deactivate_additional_pdn(deployment_mode)

    def collect_ue_ip(self, deployment_mode, pdn_name):
        logging.info("Current PDN configuration: \n{pdn_config}".format(pdn_config=Configuration().get_config()))
        apn_url = Configuration().get_apn(pdn_name)
        if deployment_mode == DeploymentMode.SA:
            return self._collect_ue_ip_in_sa(apn_url)

        return self._collect_ue_ip_in_nsa(apn_url)

    def _collect_ue_ip_in_sa(self, apn_url):
        dnn_suffix = r'\.mnc[\w\.]+'
        search_ue_ip = (r'"nas[_-]5gs.sm.pdu_addr_inf_ipv4": "([\d\.]+)"'
                        r'[\w\W]+'
                        r'"nas[_-]5gs.cmn.dnn": "{}({})?"').format(apn_url, dnn_suffix)
        search_result = self._search_ue_ip(search_ue_ip)
        if search_result:
            return search_result[0]
        return search_result

    def _collect_ue_ip_in_nsa(self, apn_url):
        dnn_suffix = r'\.mnc[\w\.]+'
        search_ue_ip = (r'"gsm_a.gm.sm.apn": "{}({})?"'
                        r'[\w\W]+'
                        r'"nas_eps.esm.pdn_ipv4": "([\d\.]+)"').format(apn_url, dnn_suffix)
        search_result = self._search_ue_ip(search_ue_ip)
        if search_result:
            return search_result[1]
        return search_result

    def _search_ue_ip(self, pattern):
        lines = self._mace_proxy.read_ota_message_details_until(pattern, wait_timeout=120)
        if not lines:
            raise GetUeIPFailure("failed to get ue ip for empty response")
        for line in lines[::-1]:
            result = re.search(pattern, line)
            if result:
                return result.groups()
        logging.info("failed to find ue ip from output={}".format(lines))
        return None

    def ports_ready(self):
        logging.info('check mace ports ready or not.')
        is_ports_ready = self._mace_proxy.is_com_ports_ready()
        logging.info('check mace ports ready response: {}'.format(is_ports_ready))
        return is_ports_ready

    def detect_builtin_apn(self):
        detect_apn = DetectAPN(MaceAtCommandExecutor(self._mace_proxy))
        detect_apn.execute()

        system_traces = self._mace_proxy.read_latest_systrace()
        system_traces = '\n'.join(system_traces)

        detect_apn_regex = r'\[AT_TX p\d+,ch\d+\](?:\r\n)?\+CGDCONT:\s+\d+,(?:"[A-Za-z0-9]+",)"([\.A-Za-z0-9]+)",'
        pattern = re.compile(detect_apn_regex)
        result = pattern.findall(system_traces)
        logging.info("UE configured APNs: {}.".format(result))
        return result

    def detect_deployment_mode(self):
        detect_act = DetectACT(MaceAtCommandExecutor(self._mace_proxy))
        detect_act.execute()
        act_collector = ACTCollector(mace=self._mace_proxy)
        acts = [int(x) for x in act_collector.collect()]
        logging.debug("act found is {}".format(acts))
        lte_acts = [ACT.E_UTRAN]
        nsa_acts = [ACT.E_UTRAN, ACT.EC_GSM_IOT_A_GB_MODE, ACT.E_UTRAN_NB_S1_MODE]
        sa_acts = [ACT.E_UTRA_CONNECTED_TO_A_5GCN,
                   ACT.E_UTRA_NR_DUAL_CONNECTIVITY,
                   ACT.NR_CONNECTED_TO_A_5GCN,
                   ACT.NG_RAN]

        if set(acts) == set(lte_acts):
            return DeploymentMode.LTE

        for act in acts:
            if act in nsa_acts:
                return DeploymentMode.NSA

        for act in acts:
            if act in sa_acts:
                return DeploymentMode.SA

        return DeploymentMode.UNKNOWN

    def get_ue_specific_methods_container(self):
        return self._mace_proxy

    def get_shell_executor(self):
        return self._remote_popen

    def lock_lte_cell(self, arfcn, pci=None):
        at_command = LockNSACell(MaceAtCommandExecutor(self._mace_proxy), arfcn=arfcn, pci=pci)
        at_command.execute()

    def unlock_lte_cell(self, arfcn, pci=None):
        at_command = UnlockNSACell(MaceAtCommandExecutor(self._mace_proxy), arfcn=arfcn, pci=pci)
        at_command.execute()

    def lock_nr_cell(self, arfcn, pci=None):
        at_command = LockSACell(MaceAtCommandExecutor(self._mace_proxy), arfcn=arfcn, pci=pci)
        at_command.execute()

    def unlock_nr_cell(self, arfcn, pci=None):
        at_command = UnlockSACell(MaceAtCommandExecutor(self._mace_proxy), arfcn=arfcn, pci=pci)
        at_command.execute()


class ApolloMaceController(MaceController):
    pass


class PetrusMaceController(MaceController):

    _DETECT_AID_REGEX = (r'\[AT_RX p\d+,ch(\d+)\]AT\+EAPNACT\=1,"{}","default"[\w\W]+'
                         r'\[AT_TX p\d+,ch(\d+)\][\w\W]*\+CGEV\: ME PDN ACT (\d+)')

    _ADB_ROOT_CMD = r"adb {serial_number_option} root"
    _DEL_IP_RULE_TABLE_CMD = r'adb {serial_number_option} shell "ip rule del table {ip_route_table_id}"'
    _SEARCH_NETWORK_CARD_NAME_CMD = r'''adb %s shell "ip route|awk '/%s/ {print $3}'"'''
    _ADD_IP_RULE_CMD = r'adb {serial_number_option} shell "ip rule add from {ue_ip} table {ip_route_table_id}"'
    _ADD_IP_ROUTE_CMD = (r'adb {serial_number_option} shell '
                         r'"ip route add default dev {network_card} table {ip_route_table_id} proto static"')
    _SHOW_IP_RULE_LIST_CMD = r'adb {serial_number_option} shell "ip rule list"'

    _INIT_IP_ROUTE_TABLE_ID = 100

    def __init__(self, config, mace_proxy):
        super(PetrusMaceController, self).__init__(config, mace_proxy)
        self._ip_route_table_id = self._INIT_IP_ROUTE_TABLE_ID
        self._voice_call_factory = self._create_voice_call_factory()

    def _create_pre_attach_factory(self):
        return PetrusMacePreAttachFactory(self._mace_proxy, self._config)

    def _create_reboot_factory(self):
        return PetrusMaceRebootFactory(self._mace_proxy)

    def _create_pdn_factory(self):
        return PetrusMacePDNFactory(self._mace_proxy,
                                    self._config)

    def _create_voice_call_factory(self):
        return MaceVoiceCallFactory(self._mace_proxy)

    def create_pre_attach(self, deployment_mode):
        return self._pre_attach_factory.create(deployment_mode)

    def create_voice_call(self, deployment_mode, name, ue_name, definition):
        return self._voice_call_factory.create(deployment_mode, name, ue_name, definition)

    def enable_vonr_capability(self):
        at_command = EIMSCFG(MaceAtCommandExecutor(self._mace_proxy),
                             EIMSCFG.VoNetwork.NR,
                             EIMSCFG.ViNetwork.NR,
                             EIMSCFG.VoWifi.OFF,
                             EIMSCFG.ViWifi.OFF,
                             EIMSCFG.Sms.ON,
                             EIMSCFG.Ims.ON)
        at_command.execute()

    def power_off_sim(self):
        at_command = ESIMPOWER(MaceAtCommandExecutor(self._mace_proxy), ESIMPOWER.POWER.OFF)
        at_command.execute()

    def power_on_sim(self):
        at_command = ESIMPOWER(MaceAtCommandExecutor(self._mace_proxy), ESIMPOWER.POWER.ON)
        at_command.execute()

    def overheating(self, oh_op=0, cc_dl=None, cc_ul=None,
                    bw_fr1_dl=None, bw_fr1_ul=None, bw_fr2_dl=None, bw_fr2_ul=None,
                    mimo_fr1_dl=None, mimo_fr2_dl=None, mimo_fr1_ul=None, mimo_fr2_ul=None):
        at_command = EGMC(MaceAtCommandExecutor(self._mace_proxy), 1, "NR_OVERHEATING", oh_op, cc_dl, cc_ul,
                          bw_fr1_dl, bw_fr1_ul, bw_fr2_dl, bw_fr2_ul,
                          mimo_fr1_dl, mimo_fr2_dl, mimo_fr1_ul, mimo_fr2_ul, None)
        at_command.execute()

    def ports_ready(self, timeout=300):
        petrus_port_names = ['USB Serial Device', 'MediaTek USB VCOM (Android)', 'MediaTek ELT Port']
        end_time = time.time() + timeout
        while time.time() < end_time:
            logging.info('check Petrus mace ports ready or not.')
            is_ports_ready = self._mace_proxy.is_com_ports_ready(port_names=petrus_port_names)
            logging.info('check Petrus mace ports ready response: {}'.format(is_ports_ready))
            if is_ports_ready:
                return is_ports_ready
            time.sleep(10)
        return False

    def detect_aid(self, pdn_name):
        system_traces = self._mace_proxy.read_latest_systrace()
        system_traces = '\n'.join(system_traces)
        apn_url = Configuration().get_apn(pdn_name)
        detect_aid_regex = self._DETECT_AID_REGEX.format(apn_url)
        result = re.search(detect_aid_regex, system_traces)
        if not result:
            raise DetectAIDFailure(system_traces)
        return result.groups()[-1]

    def clean_ip_route_rules(self):
        self._mace_proxy.run_shell_command(command=self._format_adb_root_cmd())
        while self._ip_route_table_id >= self._INIT_IP_ROUTE_TABLE_ID:
            ip_rule_list = self._mace_proxy.run_shell_command(command=self._formated_show_ip_rule_list_cmd())
            ip_rule_string = 'lookup {}'.format(self._ip_route_table_id)
            while ip_rule_string in ip_rule_list:
                self._mace_proxy.run_shell_command(command=self._formated_del_ip_rule_table_cmd())
                ip_rule_list = self._mace_proxy.run_shell_command(command=self._formated_show_ip_rule_list_cmd())
            self._ip_route_table_id -= 1

    def add_ip_route_rule(self, ue_ip):
        self._mace_proxy.run_shell_command(command=self._format_adb_root_cmd())
        search_network_card_cmd = self._formated_search_network_card_name_cmd(ue_ip)
        network_card = self._mace_proxy.run_shell_command(command=search_network_card_cmd)
        network_card = network_card.strip()
        self._mace_proxy.run_shell_command(command=self._formated_add_ip_rule_cmd(ue_ip))
        self._mace_proxy.run_shell_command(command=self._formated_add_ip_route_cmd(network_card))
        self._ip_route_table_id += 1

        ip_rule_list = self._mace_proxy.run_shell_command(command=self._formated_show_ip_rule_list_cmd())
        logging.info("ip rule list: {}".format(ip_rule_list))

    def _format_adb_root_cmd(self):
        serial_number_option = self._construct_serial_number_option()
        return self._ADB_ROOT_CMD.format(serial_number_option=serial_number_option)

    def _formated_del_ip_rule_table_cmd(self):
        serial_number_option = self._construct_serial_number_option()
        return self._DEL_IP_RULE_TABLE_CMD.format(
            serial_number_option=serial_number_option, ip_route_table_id=self._ip_route_table_id)

    def _formated_search_network_card_name_cmd(self, ue_ip):
        serial_number_option = self._construct_serial_number_option()
        return self._SEARCH_NETWORK_CARD_NAME_CMD % (serial_number_option, ue_ip)

    def _formated_add_ip_rule_cmd(self, ue_ip):
        serial_number_option = self._construct_serial_number_option()
        return self._ADD_IP_RULE_CMD.format(
            serial_number_option=serial_number_option, ue_ip=ue_ip, ip_route_table_id=self._ip_route_table_id)

    def _formated_add_ip_route_cmd(self, network_card):
        serial_number_option = self._construct_serial_number_option()
        return self._ADD_IP_ROUTE_CMD.format(
            serial_number_option=serial_number_option, network_card=network_card, ip_route_table_id=self._ip_route_table_id)

    def _formated_show_ip_rule_list_cmd(self):
        serial_number_option = self._construct_serial_number_option()
        return self._SHOW_IP_RULE_LIST_CMD.format(serial_number_option=serial_number_option)

    def _construct_serial_number_option(self):
        return "-s {}".format(self._config['serial_number']) if self._config['serial_number'] else ""


class CaymusMaceController(PetrusMaceController):

    def _create_pre_attach_factory(self):
        return CaymusMacePreAttachFactory(self._mace_proxy, self._config)

    def enable_edrx_setting(self, enable):

        if enable:
            fields_set = [(5, "SBP_ENABLE_NR_IDLE_EDRX", 1),
                          (5, "SBP_NR_EDRX_INACTIVE", 1),
                          (5, "SBP_R17_INACTIVE_STATE_PO_DETERMINATION", 1),
                          (5, "SBP_VGMM_INCLUDE_EXTENDED_PTW_IN_EDRX_IE", 1),
                          (5, "SBP_DISABLE_NR_RRC_INACTIVE_STATUS", 0)]

            for fields in fields_set:
                at_command = ESBP(MaceAtCommandExecutor(self._mace_proxy), *fields)
                at_command.execute()
                time.sleep(1)
        else:
            raise NotImplementedError("Disable eDRX setting is not supported yet.")

    def set_nr_edrx(self, circle_length_duration, extended_paging_time_window, unsolicited_result_code=True):
        """
        Set the eDRX and EPTW value for NR.
        :param circle_length_duration: The eDRX value for NR.
        :param extended_paging_time_window: The EPTW value for NR.
        :param unsolicited_result_code: Whether to enable unsolicited result code.

        <3gpp TS 24.008> v19.0.0
        In NR connected to 5GCN,
        the Paging Time Window field is ignored and the PTW value is included in the Extended Paging Time Window field.
        """
        if unsolicited_result_code:
            mode = CEDRXS.Mode.ENABLE_EDRX_AND_UNSOLICITED_RESULT_CODE
        else:
            mode = CEDRXS.Mode.ENABLE_EDRX

        act_type = CEDRXS.ACTType.NG_RAN_N1

        circle_length_duration_bits_str = CEDRXS.NRCircleDuration.get_bits_from_seconds(int(circle_length_duration))
        extended_paging_time_window_bits_str = CEDRXS.ExtendedPagingTimeWindow.get_bits_from_seconds(int(extended_paging_time_window))

        at_command = CEDRXS(MaceAtCommandExecutor(self._mace_proxy),
                            mode,
                            act_type,
                            circle_length_duration_bits_str,
                            extended_paging_time_window_bits_str)
        return at_command.execute()


class BollingerMaceController(PetrusMaceController):

    def _create_pre_attach_factory(self):
        return BollingerMacePreAttachFactory(self._mace_proxy, self._config)


class OppoMaceController(PetrusMaceController):

    _UE_PORT_USB_PORT_NAME = 'USB Serial Device (COM4)'

    _COLLECT_UE_IP_COMMANDS = [r"adb shell ip addr show ccmni0", r"adb shell ip addr show ccmni1"]

    def __init__(self, config, mace_proxy):
        super(OppoMaceController, self).__init__(config, mace_proxy)

    def _create_pre_attach_factory(self):
        return OppoMacePreAttachFactory(self._mace_proxy, self._config)

    def ports_ready(self, timeout=300):
        end_time = time.time() + timeout
        while time.time() < end_time:
            logging.info('check Petrus mace ports ready or not.')
            ports_info = self._mace_proxy.run_shell_command(r"wmic path Win32_PnPEntity")
            logging.info('check Petrus mace ports ready response: {}'.format(ports_info))
            if self._UE_PORT_USB_PORT_NAME in ports_info:
                return True
            time.sleep(10)
        return False

    def collect_ue_ip(self, deployment_mode, pdn_name):
        return self._collect_ue_ip_from_net_card()

    def _collect_ue_ip_from_net_card(self):
        for collect_command in self._COLLECT_UE_IP_COMMANDS:
            response = self._mace_proxy.run_shell_command(collect_command)
            logging.info("{} response={}".format(collect_command, response))
            ue_ip = self._search_ue_ip(response)
            if ue_ip:
                return ue_ip

        raise Exception("can not detect default ue ip")

    @staticmethod
    def _search_ue_ip(response_msg):
        result = re.search(r"inet (\d+\.\d+\.\d+\.\d+)", response_msg)
        if result:
            return result.group(1)
        return None


class ACTCollector(object):
    # [ATCI_AT_R_0 s26](2,"40499","40499","40499",13),
    # [ATCI_AT_R_0 s26](2,"China Mobile","CMCC","46002",11),
    # [ATCI_AT_R_0 s12](2,"26203","26203","26203","0000D2",11),(1,"310260","310260","310260","0000D2",11),
    # [ATCI_AT_R_0 s44](1,"26203","26203","26203","4E20",7),(1,"26203","26203","26203","0000D2",11),
    criteria_string = r'\[ATCI_AT_R_0 s\d{2}\](\(\d,(?:"[A-Za-z0-9\s]+",){3,4}(?:\d{1,2})\),)+'

    def __init__(self, mace=None):
        self._mace = mace

    def collect(self):

        lines = self._mace.read_systrace_until(self.criteria_string, wait_timeout=240)
        logging.debug('act line is {}'.format(lines[-1]))
        logging.debug('pre act line is {}'.format(lines[-2]))

        self._check_cops_response_line(lines[-1])
        self._check_prior_cops_line(lines)
        return self._get_technologies_in_response(lines[-1])

    def _check_cops_response_line(self, line):
        result = re.search(self.criteria_string, line)
        if not result:
            raise NotFoundAccessTechnology("failed to find the line containing access technology")

    @staticmethod
    def _check_prior_cops_line(lines):
        criteria_in_prior_line = r'\[ATCI_AT_R_0 s\d{2}\]'
        # search in four lines
        for line_index in range(-5, -1):
            result = re.search(criteria_in_prior_line, lines[line_index])
            if result and '+COPS:' in lines[line_index]:
                break
        else:
            raise NotFoundAccessTechnology("failed to find the line +COPS")

    @staticmethod
    def _get_technologies_in_response(line):
        access_technology_regex_str = r'\(\d,(?:"[A-Za-z0-9\s]+",){3,4}(\d{1,2})\)'
        field_parttern = re.compile(access_technology_regex_str)
        return field_parttern.findall(line)
